import android.net.Uri
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.layout.Column
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import coil.compose.AsyncImage
@Composable
fun Pick(){
  var uri by remember{mutableStateOf<Uri?>(null)}
  val launch=rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()){uri=it}
  Column{Button(onClick={launch.launch(androidx.activity.result.PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))}){Text("Pick")}
    uri?.let{AsyncImage(model=it,contentDescription=null)}}}
